/* ─── src/pages/Login.tsx ─────────────────────────────────────────
   Email + password form.  On success the AuthContext token + user
   are set and we navigate to the dashboard.                        */

import React, { useState, useCallback } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import Toast from "../components/Toast";

export default function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState<{ msg: string; type: "success" | "error" } | null>(null);

  const handleSubmit = useCallback(async (e: React.FormEvent) => {
    e.preventDefault();

    // client-side validation
    if (!email.trim() || !password.trim()) {
      setToast({ msg: "Email and password are required", type: "error" });
      return;
    }

    setLoading(true);
    try {
      await login({ email: email.trim(), password });
      setToast({ msg: "Welcome back!", type: "success" });
      setTimeout(() => navigate("/dashboard"), 600);
    } catch (err: unknown) {
      setToast({ msg: (err as Error).message || "Login failed", type: "error" });
    } finally {
      setLoading(false);
    }
  }, [email, password, login, navigate]);

  // ── shared input style ──────────────────────────
  const inputStyle: React.CSSProperties = {
    width: "100%",
    boxSizing: "border-box",
    padding: "12px 16px",
    borderRadius: 10,
    border: "1px solid #334155",
    background: "#1e293b",
    color: "#f1f5f9",
    fontSize: 14,
    fontFamily: "'Inter', sans-serif",
    outline: "none",
    transition: "border-color .2s",
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "linear-gradient(135deg, #0f172a 0%, #1e1b4b 100%)",
        padding: 24,
      }}
    >
      <Toast
        message={toast?.msg ?? null}
        type={toast?.type ?? "error"}
        onClose={() => setToast(null)}
      />

      <div
        style={{
          width: "100%",
          maxWidth: 420,
          background: "#1e293b",
          borderRadius: 18,
          padding: "40px 36px",
          border: "1px solid #334155",
          boxShadow: "0 20px 60px rgba(0,0,0,.4)",
        }}
      >
        {/* header */}
        <div style={{ textAlign: "center", marginBottom: 32 }}>
          <div
            style={{
              width: 52,
              height: 52,
              borderRadius: 14,
              background: "linear-gradient(135deg,#6366f1,#8b5cf6)",
              margin: "0 auto 16px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: 24,
            }}
          >
            ✓
          </div>
          <h1 style={{ color: "#f1f5f9", margin: 0, fontSize: 24, fontFamily: "'Outfit', sans-serif" }}>
            Welcome Back
          </h1>
          <p style={{ color: "#64748b", margin: "6px 0 0", fontSize: 14 }}>
            Sign in to your TaskFlow account
          </p>
        </div>

        {/* form */}
        <form onSubmit={handleSubmit}>
          <label style={{ color: "#94a3b8", fontSize: 13, fontWeight: 500, display: "block", marginBottom: 6 }}>
            Email
          </label>
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="you@example.com"
            style={inputStyle}
            onFocus={(e) => (e.target.style.borderColor = "#6366f1")}
            onBlur={(e) => (e.target.style.borderColor = "#334155")}
          />

          <label style={{ color: "#94a3b8", fontSize: 13, fontWeight: 500, display: "block", marginBottom: 6, marginTop: 20 }}>
            Password
          </label>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="••••••••"
            style={inputStyle}
            onFocus={(e) => (e.target.style.borderColor = "#6366f1")}
            onBlur={(e) => (e.target.style.borderColor = "#334155")}
          />

          <button
            type="submit"
            disabled={loading}
            style={{
              width: "100%",
              marginTop: 28,
              padding: "13px 0",
              borderRadius: 10,
              border: "none",
              background: loading ? "#4338ca" : "linear-gradient(135deg,#6366f1,#8b5cf6)",
              color: "#fff",
              fontSize: 15,
              fontWeight: 600,
              cursor: loading ? "not-allowed" : "pointer",
              transition: "opacity .2s",
              opacity: loading ? 0.7 : 1,
            }}
          >
            {loading ? "Signing in…" : "Sign In"}
          </button>
        </form>

        {/* footer link */}
        <p style={{ textAlign: "center", marginTop: 24, color: "#64748b", fontSize: 13 }}>
          Don't have an account?{" "}
          <Link to="/register" style={{ color: "#818cf8", textDecoration: "none", fontWeight: 600 }}>
            Sign Up
          </Link>
        </p>
      </div>
    </div>
  );
}
